const CONFIG=Object.freeze({brand:'Scope AI',productionUrl:'https://scopeai.ca',contactEmail:'info@scopeai.ca'});
const parts=[
{title:'Model',purpose:'Interprets information, reasons and proposes actions. Choose reasoning only where it improves the work.',example:'Suggest missing acceptance criteria using a story and its supporting requirements.',question:'What decision needs reasoning—and what should remain deterministic?'},
{title:'Harness & orchestration',purpose:'Coordinates the workflow or agent loop: context, state, tool calls, retries and continuation.',example:'Gather a Jira story, request analysis, pause for BA approval, then resume the approved update.',question:'What happens when the agent is uncertain or a tool fails?'},
{title:'Secure runtime',purpose:'Provides controlled execution, isolation and enforceable access boundaries for the solution.',example:'Run an agent with scoped credentials and restrict the systems and records it can access.',question:'Which boundaries must be enforced outside the model?'},
{title:'Knowledge & context',purpose:'Supplies enterprise data, business rules, procedures, instructions and relevant memory.',example:'Retrieve current policy and approved case records with traceable sources.',question:'What information can be trusted, and how do we know it is current?'},
{title:'Tools & actions',purpose:'Connects the agent to systems to retrieve information or perform authorized work.',example:'Read a record, prepare a change and publish an update only after the required approval.',question:'What action is permitted, and what requires a person’s approval?'}];
function partHTML(p,i){return `<span class="tag">COMPONENT 0${i+1} / 05</span><h3>${p.title}</h3><p>${p.purpose}</p><h4>AN ENTERPRISE EXAMPLE</h4><p>${p.example}</p><h4>THE DESIGN QUESTION</h4><p class="design-q">${p.question}</p>`}
function selectPart(i){document.getElementById('arch-detail').innerHTML=partHTML(parts[i],i);document.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.part)===i)))}
selectPart(0);document.querySelectorAll('[data-part]').forEach(b=>b.addEventListener('click',()=>selectPart(Number(b.dataset.part))));document.getElementById('all-descriptions').innerHTML=parts.map(p=>`<h3>${p.title}</h3><p>${p.purpose} ${p.example}</p><p><b>Design question:</b> ${p.question}</p>`).join('');
const faqs=[['Do we need to build from scratch?','No. We compare purchasing an existing agent, configuring your platforms, building a bounded component, or combining these approaches. The process and constraints determine the solution.'],['Can you work with our existing systems?','The starting point is your current applications, knowledge sources and access model. Discovery establishes which APIs, connectors or other approved integration paths are available and what constraints apply.'],['Where do humans remain involved?','People define the goals, validate the specification and review important outputs. Approval checkpoints depend on the impact of each action. Release decisions and sensitive business judgments remain with accountable owners.'],['How is success measured?','We agree on a baseline and measures before the pilot: handling effort, factual accuracy, rework, acceptance rate, exception frequency, cost or response time. Outcomes are evaluated against that baseline, not assumed.'],['Which platforms do you focus on?','Microsoft Foundry is the primary focus and AWS Bedrock is secondary. We also follow Google and NVIDIA to inform architecture decisions. These are platform interests, not partnership or certification claims.'],['Can we start with a small pilot?','Yes. Start with one workflow, a limited set of integrations, clear acceptance criteria and a defined review point. Discovery tests whether the opportunity is ready for a pilot.'],['How do you approach enterprise data access?','We identify necessary sources, classify the information involved and work with your owners to establish approved access. Least-privilege permissions, source traceability, retention expectations and human review are explicit design considerations.']];
document.getElementById('faqs').innerHTML=faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');
const menu=document.querySelector('.menu'),nav=document.getElementById('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){menu.click();menu.focus()}});function buildInquiryEmail(values){
 const body=['Name: '+values.name,'Work email: '+values.email,'Company: '+(values.company||'Not provided'),'','Workflow to improve:',values.workflow].join('\r\n');
 return 'mailto:'+CONFIG.contactEmail+'?subject='+encodeURIComponent('Scope AI workflow inquiry')+'&body='+encodeURIComponent(body);
}
document.querySelector('form').addEventListener('submit',e=>{
 e.preventDefault();
 if(!e.currentTarget.reportValidity()) return;
 const values=Object.fromEntries(new FormData(e.currentTarget));
 window.location.href=buildInquiryEmail(values);
});
